#!/usr/bin/env python3
"""Triage a monitoring alert against the incidents already open: page, ticket, or suppress.

The state carries the alert *and* the open incidents, so the duplicate question has something to
compare against. This is the cheapest useful thing to put in front of a pager: most alerts at
3 a.m. are the third copy of one that already woke somebody up.

    python examples/alert_triage.py
    python examples/alert_triage.py --state alert.json --json
"""
import sys

import _cli
from arbiter_client import Choice, ArbiterClient, Noul, Score

QUESTIONS = {
    "service": Choice(
        "Which service is most likely at fault, as opposed to merely reporting the symptom?",
        {
            "api-gateway": "the edge: routing, TLS, rate limiting",
            "checkout": "orders, carts, payment initiation",
            "payments": "the payment provider integration and settlement",
            "search": "the search index and query service",
            "postgres": "the primary database",
            "redis": "the cache and queue",
            "kubernetes": "the cluster itself: nodes, scheduling, networking",
        },
    ),
    "root_cause": Choice(
        "What kind of cause does this alert point at?",
        {
            "deploy": "a release or config rollout immediately before the alert",
            "dependency": "an upstream or third-party service failing",
            "capacity": "saturation: CPU, memory, connections, disk, queue depth",
            "config": "a wrong or missing setting, credential or limit",
            "network": "DNS, routing, timeouts between healthy services",
            "data": "bad or unexpected data flowing through a healthy system",
            "unknown": "nothing in the alert points at a cause",
        },
    ),
    "severity": Score(
        "How bad is the user-visible impact right now?",
        ["nothing users notice", "degraded for some", "partial outage", "full outage"],
    ),
    "is_duplicate": Noul(
        "This alert is the same incident as one of the open incidents listed in the state.",
        {"true": "same service and same failure as an open incident",
         "false": "a new and independent problem"},
    ),
}

SUPPRESS_DUPLICATE = 0.70    # attach to the open incident instead of waking anyone
PAGE_SEVERITY = 2.30         # at or past "partial outage"
TICKET_SEVERITY = 0.80

SAMPLE = {
    "alert": {
        "name": "HighErrorRate",
        "service": "checkout",
        "labels": {"severity": "critical", "env": "prod"},
        "message": ("5xx rate on checkout is 34% over the last 5 minutes; upstream payments "
                    "latency p99 is 8.2s, connection pool exhausted"),
        "started_at": "2026-03-11T02:14:07Z",
    },
    "open_incidents": [
        {"id": "INC-2291", "service": "payments", "title": "Payment provider timeouts",
         "opened_at": "2026-03-11T02:05:40Z", "status": "investigating"},
        {"id": "INC-2287", "service": "search", "title": "Index rebuild running long",
         "opened_at": "2026-03-10T19:40:00Z", "status": "monitoring"},
    ],
}


def decide(r):
    """page | ticket | suppress."""
    duplicate = r.noul("is_duplicate")
    severity = r.score("severity")
    if duplicate >= SUPPRESS_DUPLICATE:
        return "suppress", "is_duplicate %.2f >= %.2f -- attach to the open incident" % (
            duplicate, SUPPRESS_DUPLICATE)
    if severity >= PAGE_SEVERITY:
        return "page", "severity %.2f >= %.2f and not a duplicate (%.2f)" % (
            severity, PAGE_SEVERITY, duplicate)
    if severity >= TICKET_SEVERITY or duplicate >= 0.35:
        return "ticket", "severity %.2f, duplicate %.2f -- file it, do not wake anyone" % (
            severity, duplicate)
    return "suppress", "severity %.2f below %.2f -- no user-visible impact" % (
        severity, TICKET_SEVERITY)


def main() -> int:
    args = _cli.parser(__doc__).parse_args()
    state = _cli.load_state(args, SAMPLE)
    response = ArbiterClient(base_url=args.url).system_one(state, QUESTIONS, model=args.model)
    if args.json:
        return _cli.dump(response)
    action, reason = decide(response)
    _cli.render("alert triage", response, action, reason)
    return 0


if __name__ == "__main__":
    sys.exit(_cli.run(main))

"""A stand-in `/v1/systemone` over `http.server`, so the examples can be tested without a GPU.

It answers in exactly the shapes `server/app.py` produces, with probabilities derived from a
hash of the question id, so a given question always gets the same numbers and a test can assert
on a route rather than on luck. `scripted` forces specific answers where a test needs a
particular decision; `fail` turns on the three error paths the client has to explain.

Also runnable on its own, which is the quickest way to work on an example's output without a
server anywhere near you:

    python examples/tests/stub_server.py --port 8010
"""
import hashlib
import json
import math
import socketserver
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

LOADED = ["english", "multilingual", "typed-decisions"]


class _Server(ThreadingHTTPServer):
    """A ThreadingHTTPServer that does not look itself up in DNS.

    `HTTPServer.server_bind` calls `socket.getfqdn()`, which is a reverse lookup on the bind
    address and can block for half a minute on a machine with no reachable resolver. The name it
    produces only ever appears in CGI variables this stub does not generate.
    """

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        self.server_name, self.server_port = self.server_address[:2]


def _unit(*parts) -> float:
    """A stable float in [0, 1) from the given strings."""
    digest = hashlib.md5("|".join(str(p) for p in parts).encode()).digest()
    return int.from_bytes(digest[:4], "big") / 2 ** 32


def _softmax(xs):
    m = max(xs)
    e = [math.exp(x - m) for x in xs]
    total = sum(e)
    return [v / total for v in e]


def answer_for(qid: str, qdef: dict) -> dict:
    t = qdef["type"]
    if t == "noul":
        p = round(0.05 + 0.9 * _unit(qid, "noul"), 4)
        return {"type": "noul", "noul": p, "confidence": round(max(p, 1 - p), 4),
                "action": {"act_probability": 1.0}}
    crit = qdef["criteria"]
    if t == "choice":
        keys = list(crit) if isinstance(crit, dict) else list(crit)
        probs = _softmax([4.0 * _unit(qid, k) for k in keys])
        top = keys[max(range(len(keys)), key=lambda i: probs[i])]
        return {"type": "choice", "choice": top,
                "probabilities": {k: round(p, 4) for k, p in zip(keys, probs)},
                "confidence": round(max(probs), 4), "action": {"act_probability": 1.0}}
    probs = _softmax([3.0 * _unit(qid, i) for i in range(len(crit))])
    return {"type": "score",
            "score": round(sum(i * p for i, p in enumerate(probs)), 4),
            "legend": {str(i): c for i, c in enumerate(crit)},
            "probabilities": {str(i): round(p, 4) for i, p in enumerate(probs)},
            "confidence": round(max(probs), 4), "action": {"act_probability": 1.0}}


class StubServer:
    """A server on an ephemeral port. Use as a context manager; `url` is the base URL."""

    def __init__(self, api_key=None, fail=None, scripted=None):
        self.api_key = api_key
        self.fail = fail
        self.scripted = scripted or {}
        self.requests = []
        stub = self

        class Handler(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"

            def log_message(self, *a):
                pass

            def _send(self, status, payload):
                body = json.dumps(payload).encode()
                self.send_response(status)
                self.send_header("content-type", "application/json")
                self.send_header("content-length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def _error(self, status, kind, message):
                self._send(status, {"type": "error", "error": {"type": kind, "message": message}})

            def do_GET(self):
                if self.path == "/healthz":
                    return self._send(200, {"status": "ok", "version": "stub"})
                if self.path == "/readyz":
                    return self._send(200, {"status": "ready", "models": LOADED,
                                            "mode": "stub", "version": "stub"})
                if self.path == "/v1/models":
                    return self._send(200, {"object": "list", "data": [
                        {"id": "laya-%s" % n, "object": "model"} for n in LOADED]})
                return self._error(404, "not_found_error", "no route %s" % self.path)

            def do_POST(self):
                if self.path not in ("/v1/systemone", "/v1/predict"):
                    return self._error(404, "not_found_error", "no route %s" % self.path)
                raw = self.rfile.read(int(self.headers.get("content-length", 0)))
                if stub.api_key and self.headers.get("authorization") != "Bearer %s" % stub.api_key:
                    return self._error(401, "authentication_error",
                                       "missing or invalid Authorization: Bearer <key>")
                if stub.fail == "overload":
                    return self._error(529, "overloaded_error", "queue is full")
                try:
                    payload = json.loads(raw)
                except ValueError:
                    return self._error(422, "invalid_request_error",
                                       "request body is not valid JSON")
                stub.requests.append(payload)
                questions = payload.get("questions") or {}
                if not questions:
                    return self._error(422, "invalid_request_error",
                                       "questions must contain at least one question")
                if stub.fail == "budget":
                    return self._error(422, "invalid_request_error",
                                       "question has more options than head_max_len=192 can hold")
                state = json.dumps(payload.get("state"), ensure_ascii=False)
                checkpoint = "english" if state.isascii() else "multilingual"
                reason = "English Latin text" if state.isascii() else "non-Latin script"
                answers = {qid: stub.scripted.get(qid) or answer_for(qid, q)
                           for qid, q in questions.items()}
                return self._send(200, {
                    "model": "laya-%s" % checkpoint,
                    "answers": answers,
                    "usage": {"input_tokens": 40 * len(questions), "output_tokens": 0},
                    "routing": {"model": checkpoint, "repo": "stub", "reason": reason},
                    "latency_ms": 12.34,
                })

        self.httpd = _Server(("127.0.0.1", 0), Handler)
        self.url = "http://127.0.0.1:%d" % self.httpd.server_address[1]
        self.thread = threading.Thread(target=self.httpd.serve_forever,
                                       kwargs={"poll_interval": 0.02}, daemon=True)

    def __enter__(self):
        self.thread.start()
        return self

    def __exit__(self, *exc):
        self.httpd.shutdown()
        self.httpd.server_close()
        self.thread.join(timeout=5)


if __name__ == "__main__":
    import argparse

    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--port", type=int, default=8010)
    args = ap.parse_args()
    stub = StubServer()
    stub.httpd.server_close()
    stub.httpd = _Server(("127.0.0.1", args.port), stub.httpd.RequestHandlerClass)
    print("stub /v1/systemone on http://127.0.0.1:%d" % args.port)
    stub.httpd.serve_forever()

# OpenCode

Merge the `mcp` block from [`opencode.json`](opencode.json) into your `opencode.json` -- the one
in the project root, or `~/.config/opencode/opencode.json` for every project -- and replace
`/ABS/PATH` with your checkout.

OpenCode's local-server fields are `type: "local"`, `command` (an array, command and arguments
together), `environment`, and `enabled`. There is no separate `args` key.

```json
{
  "mcp": {
    "arbiter": {
      "type": "local",
      "command": ["arbiter-mcp"],
      "environment": { "ARBITER_URL": "http://localhost:8010" }
    }
  }
}
```

is the shorter form once `pip install /ABS/PATH/integrations/mcp` has put `arbiter-mcp` on your
PATH.

Every MCP server costs context, so five small tools is about the right budget. If you only want
the guard, there is no way to expose a subset from the config -- run a second copy of the server
behind a wrapper that only registers `arbiter_gate`, or just tell the agent which tool to use.
